import { runPipeline, TextStream, InterfaceTypes, Image } from 'itk-wasm';

import {
  readDicomTags,
  readOverlappingSegmentation,
  ReadOverlappingSegmentationResult,
} from '@itk-wasm/dicom';

import itkConfig from '@/src/io/itk/itkConfig';
import {
  groupByMetadata,
  refineVolumes,
  seriesLabel,
} from '@/src/catstudio/geometry';
import { reportGeometryNotes } from '@/src/catstudio/notes';
import { getWorker } from '@/src/io/itk/worker';

export interface TagSpec {
  name: string;
  tag: string;
}

export type SpatialParameters = Pick<
  Image,
  'size' | 'spacing' | 'origin' | 'direction'
>;

// volume ID => file names
export type VolumesToFileNamesMap = Record<string, string[]>;

/**
 * Filenames must be sanitized prior to being passed into itk-wasm.
 *
 * In particular, forward slashes cause FS errors in itk-wasm.
 * @param name
 * @returns
 */
function sanitizeFileName(name: string) {
  return name.replace(/\//g, '_');
}

/**
 * Returns a new File instance with a sanitized name.
 * @param file
 */
function sanitizeFile(file: File) {
  return new File([file], sanitizeFileName(file.name));
}

async function runTask(
  module: string,
  args: any[],
  inputs: any[],
  outputs: any[]
) {
  const result = await runPipeline(module, args, outputs, inputs, {
    webWorker: getWorker(),
    pipelineBaseUrl: itkConfig.pipelinesUrl,
    pipelineWorkerUrl: itkConfig.pipelineWorkerUrl,
  }).catch((error) => {
    throw new Error(
      `itk-wasm pipeline "${module}" crashed (check browser console for details)`,
      { cause: error }
    );
  });
  if (result.returnValue !== 0) {
    const detail = result.stderr?.trim() || 'unknown error';
    throw new Error(
      `itk-wasm pipeline "${module}" exited with code ${result.returnValue}: ${detail}`
    );
  }
  return result;
}

/**
 * Split and sort DICOM files
 * @async
 * @returns volumeID => file names mapping
 */
export async function splitAndSort<T>(
  instances: T[],
  mapToBlob: (inst: T, index: number) => Blob
) {
  const metaOf = (inst: T) => {
    const metadata = (inst as { metadata?: Iterable<[string, string]> | null })
      ?.metadata;
    return metadata ? new Map(metadata) : null;
  };

  // CatStudio: séries com metadados já lidos são agrupadas sem reler os
  // arquivos; só o restante passa pelo agrupamento original em WebAssembly.
  const { volumes, rest } = groupByMetadata(instances, metaOf);
  reportSeriesSplits(volumes, metaOf);
  const volumeToInstances: Record<string, T[]> = { ...volumes };
  if (rest.length) {
    const others = await splitAndSortWasm(
      rest.map((index) => instances[index]),
      (inst, i) => mapToBlob(inst, rest[i])
    );
    Object.assign(volumeToInstances, others);
  }

  // CatStudio: separa pilhas que o agrupamento por série mistura (matrizes
  // diferentes, aquisições repetidas, cópias exatas) e ordena pela normal.
  return refineVolumes(volumeToInstances, metaOf, reportGeometryNotes);
}

/** CatStudio: avisa quando uma mesma série virou mais de um volume. */
function reportSeriesSplits<T>(
  volumes: Record<string, T[]>,
  metaOf: (inst: T) => Map<string, string> | null
) {
  const bySeries = new Map<string, string[]>();
  Object.keys(volumes).forEach((key) => {
    const series = key.slice(0, key.lastIndexOf('.'));
    bySeries.set(series, [...(bySeries.get(series) ?? []), key]);
  });
  bySeries.forEach((keys, series) => {
    if (keys.length < 2) return;
    const meta = metaOf(volumes[keys[0]][0]);
    reportGeometryNotes(
      series,
      [
        {
          title: 'Série dividida em volumes',
          detail: `A série mistura ${keys.length} combinações de matriz, espessura ou número de série; cada combinação virou um volume separado.`,
        },
      ],
      meta ? seriesLabel(meta) : 'Série'
    );
  });
}

async function splitAndSortWasm<T>(
  instances: T[],
  mapToBlob: (inst: T, index: number) => Blob
) {
  const inputs = await Promise.all(
    instances.map(async (instance, index) => {
      const blob = mapToBlob(instance, index);
      const buffer = await blob.arrayBuffer();
      return {
        type: InterfaceTypes.BinaryFile,
        data: {
          path: index.toString(), // make each file name unique
          data: new Uint8Array(buffer),
        },
      };
    })
  );

  const args = [
    '--action',
    'categorize',
    '--memory-io',
    '0',
    '--files',
    ...inputs.map((fd) => fd.data.path),
  ];

  const outputs = [{ type: InterfaceTypes.TextStream }];

  const result = await runTask('dicom', args, inputs, outputs);

  // File names are indexes into input files array
  const volumeToFileIndexes = JSON.parse(
    (result.outputs[0].data as TextStream).data
  ) as VolumesToFileNamesMap;

  return Object.fromEntries(
    Object.entries(volumeToFileIndexes).map(([volumeKey, fileIndexes]) => [
      volumeKey,
      // file indexes to Files
      fileIndexes.map((fileIndex) => instances[parseInt(fileIndex, 10)]),
    ])
  ) as Record<string, T[]>;
}

/**
 * Reads a list of tags out from a given file.
 *
 * @param {File} file
 * @param {[]Tag} tags
 */
export async function readTags<T extends TagSpec[]>(
  file: File,
  tags: T
): Promise<Record<T[number]['name'], string>> {
  const tagsArgs = { tagsToRead: { tags: tags.map(({ tag }) => tag) } };

  const result = await readDicomTags(sanitizeFile(file), {
    ...tagsArgs,
    webWorker: getWorker(),
  });
  const tagValues = new Map(result.tags);

  return tags.reduce(
    (info, t) => {
      const { tag, name } = t;
      if (tagValues.has(tag)) {
        return { ...info, [name]: tagValues.get(tag) };
      }
      return info;
    },
    {} as Record<T[number]['name'], string>
  );
}

/**
 * Retrieves a slice of a volume.
 * @async
 * @param {File} file containing the slice
 * @param {Boolean} asThumbnail cast image to unsigned char. Defaults to false.
 * @returns ItkImage
 */
export async function readVolumeSlice(
  file: File,
  asThumbnail: boolean = false
) {
  const buffer = await file.arrayBuffer();

  const inputs = [
    {
      type: InterfaceTypes.BinaryFile,
      data: {
        path: sanitizeFileName(file.name),
        data: new Uint8Array(buffer),
      },
    },
  ];

  const args = [
    '--action',
    'getSliceImage',
    '--thumbnail',
    asThumbnail.toString(),
    '--file',
    sanitizeFileName(file.name),
    '--memory-io',
    '0',
  ];

  const outputs = [{ type: InterfaceTypes.Image }];

  const result = await runTask('dicom', args, inputs, outputs);

  return result.outputs[0].data as Image;
}

type DicomSegmentAttributes = {
  SegmentLabel: string;
  labelID: number;
  recommendedDisplayRGBValue: [number, number, number];
};

export type ReadOverlappingSegmentationMeta = {
  segmentAttributes: DicomSegmentAttributes[][];
};

type ReadOverlappingSegmentationResultWithRealMeta =
  ReadOverlappingSegmentationResult & {
    metaInfo: ReadOverlappingSegmentationMeta;
  };

export async function readDicomSegmentation(file: File) {
  const inputImage = sanitizeFile(file);
  const result = (await readOverlappingSegmentation(inputImage, {
    webWorker: getWorker(),
    mergeSegments: true,
  })) as ReadOverlappingSegmentationResultWithRealMeta;
  return {
    ...result,
    outputImage: result.segImage,
  };
}
